mapper.select:
SELECT EXISTS (
    SELECT 1 FROM public.recipe_like
    WHERE user_id = #{userId}
      AND recipe_id = #{recipeId}
)

mapper.delete:
DELETE FROM public.recipe_like
WHERE user_id = #{userId}
  AND recipe_id = #{recipeId}

mapper.select:
SELECT COUNT(*)
FROM public.recipe_like
WHERE recipe_id = #{recipeId}
